#define PI 3.14159265358979

float sdRegularPolygon(vec2 p, float radius, float N, float m, float _t)
{
    float a = PI * 2.0 / float(N);
    float t = atan(p.y, p.x) + a*0.5 + _t;
    float r = length(p);
    t = mod(t, a) - 0.5*a;
    return r * cos(a*0.5) / cos(t*N/2. * m) - radius;
}

float sdRegularPolygon(vec2 p, float radius, float N)
{
    return sdRegularPolygon(p,radius,N,1.,0.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Convert pixel coordinates to [-1,1] range
    vec2 uv0 = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    vec2 uv = abs(abs(uv0*2.)-.5);

    float blur = 1./iResolution.y;

    float radius = 0.5 * iResolution.x/iResolution.y / 2.;

#define SHAPE(uv, florettes, inner, rot) \
        (1.-smoothstep(bw-blur, bw+blur,\
            sdRegularPolygon(uv, radius, florettes, inner, PI*(rot))\
        ))

    float bw = 0.1;
    float lineThickness = 0.005;

    vec3 ca = vec3(1.0, 0.0, 0.0);
    ca = (0.5 + 0.5*cos(iTime+uv.xyx+vec3(2,0,4)));
    vec3 cb = vec3(0.0, 1.0, 1.0);
    cb = (0.5 + 0.5*cos(iTime+uv.xyx+vec3(4,2,0)));

    vec3 flower
        = SHAPE(uv, 4.,0.85,0.25/2.)*ca 
        + SHAPE(uv, 4.,0.85,0.25/-2.)*ca
        - SHAPE(uv, 4., 0.8, 0.) * (1.-vec3(1.,0.,0.))
        - SHAPE(uv, 8.,0.9,0.25)*0.01
        + SHAPE(uv, 8.,.5,0.)*cb;

#define CLAMP(a) clamp(a, 0.,1.)
#define CLAMPMA(a) a = CLAMP(a)
#define SQ(a, w, ma, fa, op, mb, fb) clamp(a ((ma step(w, fa)) op (mb step(w, fb))), 0.,1.)

    float plus = 0.;
    float plOff =  0.3*sin(iTime);
    plus += SQ( , 0.05 + 0.04*sin(iTime-(0.75*(PI/2.))), 1.-, abs(uv.x-plOff), +, 1.-, abs(uv.y-plOff));
    plus += SQ( , 0.05 + 0.04*sin(iTime-(0.75*(PI/2.))), 1.-, abs(uv.x+plOff), +, 1.-, abs(uv.y+plOff));
    //plus += SQ( , 0.05 + 0.05*cos(iTime-(0.75*(PI/2.))), 1.-, abs(uv.x-plOff), +, 1.-, abs(uv.y-plOff));
    //plus += SQ( , 0.1 + 0.05*sin(iTime*2.), 1.-, abs(uv.x+plOff), +, 1.-, abs(uv.y+plOff));
    //plus = CLAMP(plus);

    float sq = 0.;
    sq += SQ(1.- ,  plOff*1., , abs(uv.x), +, , abs(uv.y));
    sq += SQ(1.- , -plOff*1., , abs(uv.x), +, , abs(uv.y));

    float star = SHAPE(abs(uv+vec2(-0.5,-0.5)), 8.*1., 0.75, 0.);
    CLAMPMA(star);

    vec3 C = vec3(0.);

    C = flower;

    C = mix(C,
        vec3(star)*(0.5 + 0.5*cos(iTime*2.1+uv.xyx+vec3(2,4,0))),
        0.5+0.35*sin(iTime/2.));
    CLAMPMA(C);

    // oscillating lines
    C += CLAMP(normalize(vec3(plus+sq)) * (0.5 + 0.5*cos(iTime*4.+uv.xyx+vec3(0,2,4))));
    C += CLAMP(normalize(vec3(1.)-vec3(plus+sq)) * (0.5 - 0.5*cos(iTime*4.+uv.xyx+vec3(0,2,4))));

    fragColor = vec4(C, 1.0);
}
